export default { apiVersion: 1, languageVersion: 3, name: "title", kind: "generator", mode: "dynamic", width: 1920, height: 1080, durationSeconds: 5, seed: 42,
  parameters: { title: { type: "text", title: "标题", default: "让创作保持一致", maxLength: 160 }, subtitle: { type: "text", title: "说明", default: "一个想法，一种表达", maxLength: 200 } },
  render(ctx) {
    const s = ctx.style;
    const inset = s.shape.spacing2 * ctx.height;
    const p = tween(ctx.time, 0.15, s.motion.enterDuration, 0, 1, s.motion.enterEase);
    const out = tween(ctx.time, 4.2, s.motion.exitDuration, 1, 0, s.motion.exitEase);
    const alpha = clamp(p, 0, 1) * clamp(out, 0, 1);
    const size = s.typeScale.xl * ctx.height;
    return [group({ id: "component", x: ctx.width * 0.12, y: ctx.height * 0.32 + (1 - p) * ctx.height * 0.035, opacity: alpha }, [
      rect({ id: "plate", x: 0, y: 0, width: ctx.width * 0.72, height: ctx.height * .32, fill: s.palette.surface, radius: s.shape.radius * ctx.height }),
      rect({ id: "accent", x: 0, y: 0, width: s.shape.strokeWidth * ctx.height * 2, height: ctx.height * .32, fill: s.palette.accent }),
      text({ id: "title", x: inset, y: inset, text: ctx.params.title, fontFamily: s.fonts.display.family, fontWeight: s.fonts.display.weight, fontSize: size, color: s.palette.fg, baseline: "top", maxWidth: ctx.width * 0.72 - inset * 2, wrap: true, maxLines: 1 }),
      text({ id: "subtitle", x: inset, y: inset + size * 1.25, text: ctx.params.subtitle, fontFamily: s.fonts.body.family, fontWeight: s.fonts.body.weight, fontSize: s.typeScale.sm * ctx.height, color: s.palette.muted, baseline: "top", maxWidth: ctx.width * 0.72 - inset * 2, wrap: true, maxLines: 1 })
    ])];
  }
}

